#!/usr/bin/env python3
import base64
import gzip
import hashlib

_PAYLOAD = """"""
_raw = gzip.decompress(base64.b64decode(_PAYLOAD))
assert len(_raw) == 50180
assert hashlib.sha256(_raw).hexdigest() == "860549fad2b09eafe866a8ae81620a132d208bdf14923ca8285acc1906019a34"
exec(compile(_raw, "<rd04-two-cell-materializer>", "exec"), {"__name__": "__main__", "__file__": __file__})
